import{_ as i,o as a,c as t,a3 as o}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"各类术语的词义统一与词典制作","description":"","frontmatter":{"translationSource":{"title":"各类术语的词义统一与词典制作","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=wE5eqNGummvOtoCzUO3RQK","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/unifying-terminology-and-building-a-dictionary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/unifying-terminology-and-building-a-dictionary"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/unifying-terminology-and-building-a-dictionary"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/unifying-terminology-and-building-a-dictionary"}]]},"headers":[],"relativePath":"zh/unifying-terminology-and-building-a-dictionary.md","filePath":"zh/page-wE5eqNGummvOtoCzUO3RQK.md"}'),r={name:"zh/unifying-terminology-and-building-a-dictionary.md"};function s(l,n,e,p,d,c){return a(),t("div",null,[...n[0]||(n[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="各类术语的词义统一与词典制作" aria-hidden="true"></span><h1 id="各类术语的词义统一与词典制作" tabindex="-1">各类术语的词义统一与词典制作 <a class="header-anchor" href="#各类术语的词义统一与词典制作" aria-label="Permalink to &quot;各类术语的词义统一与词典制作&quot;">​</a></h1><blockquote><p>源页面 ID：<code>wE5eqNGummvOtoCzUO3RQK</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=wE5eqNGummvOtoCzUO3RQK" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span id="source-block-87n6trkPmz1YpdRnOZKk1M"></span></p><span class="logistics-source-anchor" id="波动分析" aria-hidden="true"></span><h4 id="波动分析" tabindex="-1"><strong>波动分析</strong> <a class="header-anchor" href="#波动分析" aria-label="Permalink to &quot;**波动分析**&quot;">​</a></h4><ul><li><p><strong>t_n</strong>: 第n个物品到达输出端的时刻，n∈ℤ⁺，单位tick（1 tick = 2秒）</p></li><li><p><strong>T_avg</strong>: 平均间隔，定义为lim_{n→∞} t_n/n，数值上等于L/K或1/d，单位tick</p></li><li><p><strong>M_dev</strong>: 依时波动幅度，定义为sup_{n}(t_n - n·T_avg) - inf_{n}(t_n - n·T_avg)，单位tick，表征物品流的时间稳定性与发电蓄电量波动</p></li><li><p><strong>M_dev_bound</strong>: 波动幅度理论的上界，如M_dev &lt; 2表示波动小于2 tick（4秒）</p></li></ul><p><span id="source-block-nd8EFDucO3qUjzXot5uD3c"></span></p><span class="logistics-source-anchor" id="均匀度定义" aria-hidden="true"></span><h4 id="均匀度定义" tabindex="-1"><strong>均匀度定义</strong> <a class="header-anchor" href="#均匀度定义" aria-label="Permalink to &quot;**均匀度定义**&quot;">​</a></h4><ul><li><p><strong>完美均匀</strong>: 满足M_dev ≤ 1（或严格&lt;1）的均匀性，即Bresenham-1均匀，证明闰年规则的均匀性时专用的名词，不普遍</p></li><li><p><strong>Bresenham-M均匀</strong>: 对累积物品量S_cum(n)，满足∀n: |S_cum(n) - d·n| &lt; M，M为偏差上界</p></li><li><p><strong>Beatty-M均匀</strong>: 对区间物品量S_cum(i,j)，满足∀i,j: |S_cum(i,j) - (j-i)·d| &lt; M，等价于<strong>局部均匀</strong>（与最均匀情况的间隔的极差≤1）</p></li><li><p><strong>Cipolla-M物品均匀</strong>: 对累积偏差的极差，满足sup_n(S_cum(n)-d·n) - inf_n(S_cum(n)-d·n) &lt; M</p></li><li><p><strong>Cipolla-M时间均匀</strong>: 对到达时间偏差的极差，满足sup_n(t_n - n/d) - inf_n(t_n - n/d) &lt; M</p></li></ul><p><span id="source-block-u0Z9YrEEmpvcjFnyhcJlra"></span></p><span class="logistics-source-anchor" id="序列与误差" aria-hidden="true"></span><h4 id="序列与误差" tabindex="-1"><strong>序列与误差</strong> <a class="header-anchor" href="#序列与误差" aria-label="Permalink to &quot;**序列与误差**&quot;">​</a></h4><ul><li><p><strong>t_i</strong>: 输出序列中第i个1的位置（索引从1开始），i=1,...,K</p></li><li><p><strong>L</strong>: 序列长度，定义为max(t_i)，即最后一个1的位置，单位tick</p></li><li><p><strong>K</strong>: 序列中1的个数（物品总数），原记作N，为避免与计数树叶数冲突改用K</p></li><li><p><strong>d</strong>: 占空比，定义为K/L，表示单位时间内的物品密度，单位个/tick</p></li><li><p><strong>T_ideal</strong>: 理想间隔，定义为L/K = 1/d，表示理论上的平均间距，单位tick</p></li><li><p><strong>E(i)</strong>: 第i次输出误差，定义为t_i - i·T_ideal，等于k_i/K（是1/K的整数倍），表征实际位置与理想位置的偏离</p></li></ul><p><span id="source-block-qGXqVRZXUne5DLsTLzkHQd"></span></p><span class="logistics-source-anchor" id="计数树与周期" aria-hidden="true"></span><h4 id="计数树与周期" tabindex="-1"><strong>计数树与周期</strong> <a class="header-anchor" href="#计数树与周期" aria-label="Permalink to &quot;**计数树与周期**&quot;">​</a></h4><ul><li><p><strong>N_leaf</strong>: 计数树叶节点数，等于2^m·3^n，其中m为二分节点数，n为三分节点数</p></li><li><p><strong>P_cycle</strong>: 系统周期，对于带回流的计数树等于k·(N_leaf - |𝒮|)，单位tick，k为外部输入周期参数（每k tick输入1个）</p></li><li><p><strong>𝒮</strong>: Skip集（花体S），计数树中触发回流的计数值集合，为避免与累积和S_cum(n)混淆改用花体</p></li><li><p><strong>𝒪</strong>: Output集（花体O），计数树中触发输出的计数值集合</p></li><li><p><strong>𝒫</strong>: Pass集（花体P），计数树中触发抛弃的计数值集合</p></li></ul><p><span id="source-block-YTu7OW8ti2uibRIzIxgPvL"></span></p><span class="logistics-source-anchor" id="蓄电量分析" aria-hidden="true"></span><h4 id="蓄电量分析" tabindex="-1"><strong>蓄电量分析</strong> <a class="header-anchor" href="#蓄电量分析" aria-label="Permalink to &quot;**蓄电量分析**&quot;">​</a></h4><ul><li><p><strong>E_n</strong>: 第n颗电池投入发电瞬间的蓄电量，单位焦耳</p></li><li><p><strong>V</strong>: 周期内蓄电量最大值，V = sup_n E_n</p></li><li><p><strong>ΔE</strong>: 蓄电量极差，定义为E_max - E_min，理论满足ΔE &lt; 128000 - 40P + P·M_dev（单位焦耳，其中P为设置功率）</p></li></ul><p><span id="source-block-uAA4vJGoG1SwzFwmGDrPX2"></span></p><span class="logistics-source-anchor" id="构造运算" aria-hidden="true"></span><h4 id="构造运算" tabindex="-1"><strong>构造运算</strong> <a class="header-anchor" href="#构造运算" aria-label="Permalink to &quot;**构造运算**&quot;">​</a></h4><ul><li><p><strong>取补</strong>: 序列01互换运算，新占空比d&#39; = 1-d</p></li><li><p><strong>K-取商</strong>: 每K个物品保留第1个的稀疏化运算，新占空比d&#39; = d/K</p></li></ul><p><span id="source-block-QSfK3MpskztDYLzXXre8iH"></span></p><span class="logistics-source-anchor" id="优先级分析" aria-hidden="true"></span><h4 id="优先级分析" tabindex="-1">优先级分析 <a class="header-anchor" href="#优先级分析" aria-label="Permalink to &quot;优先级分析&quot;">​</a></h4><ul><li><p><strong>优先输出</strong>: 指阻尼理论或类似理论解释的储物箱或各自工厂或多口暗管出口处的输出存在优先级的现象。</p></li><li><p><strong>优先输入</strong>: 指汇流器与分流器直接连接时的汇流器有优先接受某一方向的输入的优先级现象</p></li></ul><p><span id="source-block-N4r53hk8elxexgxAqqxLUd"></span></p><span class="logistics-source-anchor" id="常用词" aria-hidden="true"></span><h4 id="常用词" tabindex="-1">常用词 <a class="header-anchor" href="#常用词" aria-label="Permalink to &quot;常用词&quot;">​</a></h4><ul><li><p><strong>轮询</strong>:</p></li><li><p>优先级</p></li><li><p>231理论</p></li></ul></div>',1)])])}const h=i(r,[["render",s]]);export{u as __pageData,h as default};
